/**
 * Whether the dashboard should ask the API now: only while its tab is visible and the operator has
 * touched it (a key, the pointer, a scroll) within `IDLE_MS`. Polling and live streams pause otherwise
 * and resume at the next touch, so a tab left open asks nothing: on Cloudflare every read is a request
 * of the day's budget (100,000 for the Worker and as many for the Durable Objects on the Free plan),
 * shared with the bot.
 *
 * On Cloudflare (`ApiApp.target` `durable`) polling is also slower (`every`): each list read calls the
 * index and every conversation's object.
 */

import { useEffect, useRef, useSyncExternalStore } from "react";

/** Without a touch for this long, the dashboard stops asking. */
export const IDLE_MS = 5 * 60_000;
/** Polling is this many times slower on Cloudflare. */
export const CLOUDFLARE_SLOWER = 3;

const TOUCHES = ["pointerdown", "pointermove", "keydown", "wheel", "touchstart", "focus"] as const;

let last = Date.now();
let timer: ReturnType<typeof setTimeout> | undefined;
let target = "server";
const listeners = new Set<() => void>();

const compute = (): boolean => document.visibilityState === "visible" && Date.now() - last < IDLE_MS;
let active = compute();

function update(): void {
  const next = compute();
  if (next === active) return;
  active = next;
  for (const listener of listeners) listener();
}

function touch(): void {
  // The pointer moves often: once a second is enough.
  if (active && Date.now() - last < 1000) return;
  last = Date.now();
  update();
  clearTimeout(timer);
  timer = setTimeout(update, IDLE_MS + 100);
}

for (const name of TOUCHES) window.addEventListener(name, touch, { passive: true, capture: true });
document.addEventListener("visibilitychange", () => (document.visibilityState === "visible" ? touch() : update()));
timer = setTimeout(update, IDLE_MS + 100);

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Whether the tab is visible and the operator was there within `IDLE_MS`. */
export function useActive(): boolean {
  return useSyncExternalStore(subscribe, () => active);
}

/** Where the App runs (`ApiApp.target`), which the shell says once it read the composition. */
export function setTarget(value: string): void {
  target = value;
}

/** `ms` for this host: slower on Cloudflare. */
export function every(ms: number): number {
  return target === "durable" ? ms * CLOUDFLARE_SLOWER : ms;
}

/**
 * Calls `tick` every `everyMs` while the dashboard is active (`useActive`), and at once when it
 * becomes active again after a pause. `undefined` polls nothing. Returns whether it is active.
 */
export function usePolling(tick: () => void, everyMs: number | undefined): boolean {
  const isActive = useActive();
  const saved = useRef(tick);
  saved.current = tick;
  const wasActive = useRef(isActive);

  useEffect(() => {
    if (everyMs === undefined || !isActive) {
      wasActive.current = isActive;
      return;
    }
    if (!wasActive.current) saved.current();
    wasActive.current = true;
    const interval = setInterval(() => saved.current(), everyMs);
    return () => clearInterval(interval);
  }, [isActive, everyMs]);

  return isActive;
}

/**
 * The admin API's JSON: what every route of admin-api answers, typed. The dashboard (`src/dashboard/`,
 * a project of its own) keeps an identical copy, `src/dashboard/src/lib/admin-api.ts`: no imports, so
 * it compiles there too. Change both together; the kit's tests check they are the same.
 *
 * Every route needs an operator (`admin.auth`): `Authorization: Bearer <PIKIT_ADMIN_TOKEN>` with
 * admin-auth-token, or the session cookie a browser got from `POST /admin/api/session` (then a `POST`
 * also carries `x-pikit-admin: 1`). An error is an `ApiError` with its status.
 *
 * **The dashboard is a channel of its own.** It reads every conversation, and writes only into its own
 * (keys `dashboard:<uuid>`, `POST /admin/api/conversations`) and as follow-ups to another channel's
 * conversation, whose answers it keeps: the request ids of its messages start with `dashboard:`, and a
 * run only they started is never delivered to the conversation's chat.
 *
 * | Route | Answer |
 * |---|---|
 * | `GET /admin/api/app` | `ApiApp`: the composition (`APP_DESCRIPTION`, no secrets) |
 * | `POST /admin/api/session` | the credential once → `200 ApiSession` and a session cookie (a browser's) |
 * | `DELETE /admin/api/session` | `204`: the session cookie cleared |
 * | `GET /admin/api/conversations?limit&cursor` | `ApiPage<ApiConversation>`, the most recently active first |
 * | `POST /admin/api/conversations` | `ApiStartRequest` → `201 ApiStartResponse`: a conversation of the dashboard's own |
 * | `GET /admin/api/conversations/:id` | `ApiConversation` |
 * | `GET /admin/api/conversations/:id/transcript?limit&cursor` | `ApiPage<ApiTranscriptEntry>`, newest first |
 * | `GET /admin/api/conversations/:id/events` | server-sent events, one `ApiEvent` per `data:` line; `snapshot` first |
 * | `POST /admin/api/conversations/:id/messages` | `ApiSendRequest` → `202 ApiSendResponse` |
 * | `POST /admin/api/conversations/:id/abort` | `200 ApiAbortResponse` |
 * | `POST /admin/api/conversations/:id/reset` | `200 ApiResetResponse` |
 * | `GET /admin/api/delivery/pending?limit&cursor` | `ApiPage<ApiPendingPiece>`, oldest stored first (with `outbound.queue`) |
 * | `GET /admin/api/delivery/receipts?after&limit` | `ApiReceiptsPage`, in the order they settled (with `outbound.queue`) |
 */

/** The keys of the dashboard's own conversations: `dashboard:<uuid>`. No other channel makes one. */
export const DASHBOARD_KEY_PREFIX = "dashboard:";

/** Whether `key` is one of the dashboard's own conversations. */
export const isDashboardKey = (key: string | undefined): boolean => key?.startsWith(DASHBOARD_KEY_PREFIX) === true;

/** How every message from the dashboard starts, as the agent reads it (`operatorPrompt`). */
export const OPERATOR_NOTE = "[From the operator, in the pikit dashboard";

/**
 * `text` as the agent reads it, sent from the dashboard to the conversation `key`: a first line says it
 * comes from the operator, and, in another channel's conversation, that its user sees neither it nor
 * the answer.
 */
export function operatorPrompt(key: string, text: string): string {
  const note = isDashboardKey(key) ? `${OPERATOR_NOTE}.]` : `${OPERATOR_NOTE}: the user of this conversation does not see this message or your answer to it.]`;
  return `${note}\n${text}`;
}

/** What a conversation cost: every model call and tool summed (pi-ai's `Usage`). */
export interface ApiUsage {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  totalTokens: number;
  cost: { input: number; output: number; cacheRead: number; cacheWrite: number; total: number };
}

/** One conversation of the runtime. */
export interface ApiConversation {
  /**
   * What `:id` is in the routes, opaque (encode it in a path): the runtime's id on a server,
   * `<key>~<the object's id>` on Cloudflare, where each conversation's object numbers its own.
   */
  conversationId: string;
  /** Its conversation key (`telegram:12345`) and agent, once a message reached it. */
  key?: string;
  agent?: string;
  /** Whether a run is going now. */
  busy: boolean;
  /** Epoch ms of its newest message. */
  lastActivity?: number;
  usage: ApiUsage;
  /**
   * Whether its key points to it now. `false` for a conversation a reset left behind: it can be read,
   * not talked to. Absent when it has no key yet.
   */
  current?: boolean;
}

/** One page, and the cursor of the next (absent on the last page). */
export interface ApiPage<T> {
  items: T[];
  next?: string;
}

/** One entry of a conversation's history: its messages in the runtime's JSON (pi-ai's `Message`). */
export interface ApiTranscriptEntry {
  id: string;
  /** `message`, `pi.reset`, …: the runtime's words. */
  kind: string;
  messages: unknown[];
}

/**
 * One live event of a conversation, in the runtime's JSON. The first is a `snapshot` of what the
 * conversation is now; a client that fell behind gets a new `snapshot`, so a view is rebuilt from the
 * last `snapshot` and the events after it, never from a count of events.
 */
export interface ApiEvent {
  type: string;
  [field: string]: unknown;
}

/**
 * A message from an operator to a conversation: a follow-up (with a run going it waits for it), whose
 * answer stays in the dashboard. The agent reads it after `operatorPrompt`'s first line.
 */
export interface ApiSendRequest {
  text: string;
  /**
   * Its identity: the same one sent again does not run again. `dashboard:` then 1 to 118 of
   * `A-Z a-z 0-9 . _ ~ : -`. Absent, admin-api makes one.
   */
  requestId?: string;
}

export interface ApiSendResponse {
  requestId: string;
  /** `started`: a run started; `queued`: it waits for the run going; `duplicate`: already there. */
  admission: "started" | "queued" | "duplicate";
}

/** A new conversation of the dashboard's own, with its first message. */
export interface ApiStartRequest {
  /** One of the App's agents: the keys of `agent.definition` in `ApiApp.capabilities`. */
  agent: string;
  text: string;
  /** As `ApiSendRequest.requestId`. */
  requestId?: string;
}

export interface ApiStartResponse extends ApiSendResponse {
  conversationId: string;
  /** `dashboard:<uuid>`. */
  key: string;
}

/** A browser's session, opened. */
export interface ApiSession {
  /** The operator's id, as `admin.auth` names it. */
  operator: string;
}

export interface ApiAbortResponse {
  conversationId: string;
}

export interface ApiResetResponse {
  key: string;
  /** The conversation the key pointed to, kept and readable. */
  previousConversationId: string;
  /** The new, empty conversation the key points to now. */
  conversationId: string;
}

/** A piece of an answer not delivered yet (`outbound.queue`'s `pending`). Never its text. */
export interface ApiPendingPiece {
  idempotencyKey: string;
  /** Which of the answer's pieces: 0 is the first. */
  index: number;
  channel: string;
  conversationKey: string;
  /** `queued`: never tried; `sending`: in flight; `retrying`: tried, waiting to go again. */
  state: "queued" | "sending" | "retrying";
  attempts: number;
  /** Epoch ms before which it is not tried again; absent while sending. */
  nextAttemptAt?: number;
  /** Why its last try did not deliver it, short. */
  lastError?: string;
  /** Its next send may repeat one that reached the platform. */
  possibleDuplicate: boolean;
  storedAt: number;
}

/** A piece that settled (`outbound.queue`'s `receipts`), with the cursor to read after it. */
export interface ApiReceipt {
  cursor: string;
  idempotencyKey: string;
  index: number;
  channel: string;
  conversationKey: string;
  attempts: number;
  outcome: { kind: "delivered"; platformMessageId: string; possibleDuplicate: boolean } | { kind: "abandoned"; reason: string };
  /** Epoch ms when it settled. */
  at: number;
}

/** Receipts after a cursor: `next` is the last one's, to read on from; `gap`: some were pruned before this read. */
export interface ApiReceiptsPage {
  items: ApiReceipt[];
  gap: boolean;
  next?: string;
}

/**
 * The composition (`AppDescription`, K13): JSON, no secrets. A config value that looks like one (under a
 * key such as `token`, `secret`, `password`, `apiKey`, or shaped like a credential) is `[redacted]`.
 */
export interface ApiApp {
  version: number;
  target: string;
  components: { name: string; version?: string; provides: string[]; requires: string[]; optional: string[] }[];
  capabilities: Record<string, { providers: string[]; selected?: string; keys?: Record<string, string> }>;
  pipelines: Record<string, unknown[]>;
  config: Record<string, unknown>;
}

export interface ApiError {
  /**
   * `unauthorized`, `not_found`, `not_installed`, `invalid_request`, `invalid_cursor`, `no_agent`,
   * `not_current`, `unknown_agent`; `unavailable` (503) when, on Cloudflare, a conversation's object
   * did not answer.
   */
  error: string;
  message?: string;
}

/**
 * The admin API (admin-api, `/admin/api/*`), from the browser. Its JSON is typed in `admin-api.ts`, an
 * identical copy of admin-api's own `api.ts` (`src/pikit/admin-api/api.ts`): change both together.
 *
 * **Signing in** (`signIn`) posts the operator's token once, to `POST /admin/api/session`, which
 * answers with a session cookie (HttpOnly, SameSite=Strict, sent to `/admin/api/` only, expiring):
 * the token is kept nowhere, and no script can read the session. `signOut` clears it. Every call
 * carries the header `x-pikit-admin: 1`, which a page of another site cannot send, so the cookie
 * alone changes nothing. An `admin.auth` without browser sessions (`404 not_installed`): the token is
 * kept in this page's memory only, and asked again after a reload.
 *
 * A browser's `EventSource` cannot send the header, so live events are read with `fetch`.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { usePolling } from "./activity.ts";
import type { ApiError, ApiEvent } from "./admin-api.ts";

export type * from "./admin-api.ts";

const API = "/admin/api";
/** `ADMIN_CLIENT_HEADER` (@pikit/contracts): what makes a call the dashboard's own. */
const CLIENT_HEADER = "x-pikit-admin";

/** The token, when the API has no browser sessions: this page's memory only. */
let memoryToken: string | undefined;

/** An answer that is not a success: its status and the API's error. */
export class ApiFailure extends Error {
  readonly status: number;
  readonly body: ApiError;
  constructor(status: number, body: ApiError) {
    super(body.message ?? body.error);
    this.status = status;
    this.body = body;
  }
}

/** Listeners told when the API refuses the token (401): the app asks for it again. */
const unauthorized = new Set<() => void>();
export function onUnauthorized(listener: () => void): () => void {
  unauthorized.add(listener);
  return () => unauthorized.delete(listener);
}

function headers(extra?: HeadersInit): Headers {
  const all = new Headers(extra);
  all.set(CLIENT_HEADER, "1");
  if (memoryToken !== undefined) all.set("authorization", `Bearer ${memoryToken}`);
  return all;
}

/**
 * Signs in with the operator's `token` (PIKIT_ADMIN_TOKEN with admin-auth-token): a session cookie,
 * or, without browser sessions, the token in memory. Throws an `ApiFailure` (`401`: not the token).
 */
export async function signIn(token: string): Promise<void> {
  const response = await fetch(`${API}/session`, { method: "POST", headers: { [CLIENT_HEADER]: "1", authorization: `Bearer ${token}` } });
  if (response.ok) {
    memoryToken = undefined;
    return;
  }
  const body = (await response.json().catch(() => ({ error: `http_${response.status}` }))) as ApiError;
  if (response.status !== 404 || body.error !== "not_installed") throw new ApiFailure(response.status, body);
  // No sessions: the token goes with every call, from memory, if the API takes it.
  memoryToken = token;
  try {
    await api("/app");
  } catch (error) {
    memoryToken = undefined;
    throw error;
  }
}

/** Signs out: the session cookie cleared (and the token forgotten). */
export async function signOut(): Promise<void> {
  memoryToken = undefined;
  await fetch(`${API}/session`, { method: "DELETE", headers: { [CLIENT_HEADER]: "1" } }).catch(() => undefined);
}

async function failure(response: Response): Promise<ApiFailure> {
  if (response.status === 401) for (const listener of unauthorized) listener();
  const body = (await response.json().catch(() => ({ error: `http_${response.status}` }))) as ApiError;
  return new ApiFailure(response.status, body);
}

/** `GET` (or `init`'s method) of `path` under /admin/api, as JSON. */
export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(`${API}${path}`, { ...init, headers: headers(init.headers) });
  if (!response.ok) throw await failure(response);
  return (await response.json()) as T;
}

/** `POST` of `body` (JSON) to `path` under /admin/api. */
export function post<T>(path: string, body?: unknown): Promise<T> {
  return api<T>(path, {
    method: "POST",
    headers: { "content-type": "application/json" },
    ...(body !== undefined && { body: JSON.stringify(body) }),
  });
}

/**
 * Follows `path`'s server-sent events until `signal` aborts or the stream ends: each `data:` line is
 * one event. Resolves when the stream ends; rejects when it cannot start.
 */
export async function follow(path: string, onEvent: (event: ApiEvent) => void, signal: AbortSignal): Promise<void> {
  const response = await fetch(`${API}${path}`, { headers: headers({ accept: "text/event-stream" }), signal });
  if (!response.ok || response.body === null) throw await failure(response);
  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) return;
      buffer += value;
      let end = buffer.indexOf("\n\n");
      while (end !== -1) {
        const frame = buffer.slice(0, end);
        buffer = buffer.slice(end + 2);
        const data = frame
          .split("\n")
          .filter((line) => line.startsWith("data: "))
          .map((line) => line.slice(6))
          .join("\n");
        if (data !== "" && !frame.startsWith("event: error")) onEvent(JSON.parse(data) as ApiEvent);
        end = buffer.indexOf("\n\n");
      }
    }
  } catch (error) {
    if (signal.aborted) return;
    throw error;
  } finally {
    reader.releaseLock();
  }
}

export interface Loaded<T> {
  data: T | undefined;
  error: Error | undefined;
  loading: boolean;
  reload(): void;
}

/** `GET path`, again on `reload()`, and every `everyMs` when given while the dashboard is active. `null` loads nothing. */
export function useApi<T>(path: string | null, everyMs?: number): Loaded<T> {
  const [data, setData] = useState<T>();
  const [error, setError] = useState<Error>();
  const [loading, setLoading] = useState(path !== null);
  const [round, setRound] = useState(0);
  const current = useRef(path);
  current.current = path;

  useEffect(() => {
    if (path === null) return;
    let live = true;
    setLoading(true);
    api<T>(path)
      .then((value) => live && current.current === path && (setData(value), setError(undefined)))
      .catch((thrown: unknown) => live && setError(thrown instanceof Error ? thrown : new Error(String(thrown))))
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, [path, round]);

  const reload = useCallback(() => setRound((n) => n + 1), []);
  // Only while the operator is here (`activity.ts`).
  usePolling(reload, path === null ? undefined : everyMs);
  return { data, error, loading, reload };
}

/** Small formatting helpers shared by views. */

import type { ApiUsage } from "./api.ts";

/** A cost in dollars: `$0.0042`, `$1.23`. */
export function formatCost(usage: ApiUsage | undefined): string {
  const total = usage?.cost.total ?? 0;
  if (total === 0) return "$0";
  return `$${total < 0.01 ? total.toFixed(4) : total.toFixed(2)}`;
}

/** Tokens, short: `950`, `12.3k`, `1.2M`. */
export function formatTokens(count: number): string {
  if (count < 1000) return String(count);
  if (count < 1_000_000) return `${(count / 1000).toFixed(1)}k`;
  return `${(count / 1_000_000).toFixed(1)}M`;
}

const relative = new Intl.RelativeTimeFormat(undefined, { numeric: "auto" });

/** `3 minutes ago`, from epoch milliseconds. */
export function formatAgo(at: number | undefined, now = Date.now()): string {
  if (at === undefined) return "—";
  const seconds = Math.round((at - now) / 1000);
  const steps: [Intl.RelativeTimeFormatUnit, number][] = [
    ["second", 60],
    ["minute", 60],
    ["hour", 24],
    ["day", 30],
    ["month", 12],
  ];
  let value = seconds;
  for (const [unit, size] of steps) {
    if (Math.abs(value) < size) return relative.format(value, unit);
    value = Math.round(value / size);
  }
  return relative.format(value, "year");
}

/**
 * A small router over the History API, under /admin (admin-api answers every path but `/admin/assets/`
 * and its files with index.html, so a reload of any page works). Paths here are relative to /admin:
 * `/conversations/abc` is `/admin/conversations/abc`.
 *
 * A parameter is one path segment, encoded in a link (`encodeURIComponent`: an id such as
 * `email:ana@empresa.com~1` or one with `/`) and decoded by `match`.
 */

import { type AnchorHTMLAttributes, useSyncExternalStore } from "react";

export const BASE = "/admin";

function subscribe(onChange: () => void): () => void {
  window.addEventListener("popstate", onChange);
  return () => window.removeEventListener("popstate", onChange);
}

const path = (): string => {
  const { pathname } = window.location;
  const relative = pathname.startsWith(BASE) ? pathname.slice(BASE.length) : pathname;
  return relative === "" ? "/" : relative;
};

/** The current path, relative to /admin. */
export function usePath(): string {
  return useSyncExternalStore(subscribe, path);
}

export function navigate(to: string, options: { replace?: boolean } = {}): void {
  const url = `${BASE}${to}`;
  if (options.replace === true) window.history.replaceState(null, "", url);
  else window.history.pushState(null, "", url);
  window.dispatchEvent(new PopStateEvent("popstate"));
}

/**
 * The parameters of `pattern` (`/conversations/:id`) in `pathname`, or `undefined` when it does not
 * match.
 */
export function match(pattern: string, pathname: string): Record<string, string> | undefined {
  const want = pattern.split("/").filter(Boolean);
  const have = pathname.split("/").filter(Boolean);
  if (want.length !== have.length) return undefined;
  const params: Record<string, string> = {};
  for (const [i, segment] of want.entries()) {
    const value = have[i] ?? "";
    if (segment.startsWith(":")) {
      try {
        params[segment.slice(1)] = decodeURIComponent(value);
      } catch {
        return undefined;
      }
    } else if (segment !== value) return undefined;
  }
  return params;
}

/** The path of a page with `id` as one segment: `pagePath("/conversations", id)`. */
export function pagePath(base: string, id: string): string {
  return `${base}/${encodeURIComponent(id)}`;
}

/** A link inside the dashboard: `to` is relative to /admin. */
export function Link({ to, onClick, ...rest }: AnchorHTMLAttributes<HTMLAnchorElement> & { to: string }) {
  return (
    <a
      {...rest}
      href={`${BASE}${to}`}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey) return;
        event.preventDefault();
        navigate(to);
      }}
    />
  );
}

/**
 * Views: each folder of `src/views/` is one, found when the dashboard is built (nothing is loaded
 * at run time). Its `index.tsx` default-exports `defineView({ … })`:
 *
 *   export default defineView({
 *     id: "memory",                       // the folder's name; its pages live under /memory
 *     title: "Memory",
 *     icon: Brain,
 *     requires: ["memory"],               // shown only when these capabilities are installed
 *     pages: [{ path: "/memory", component: MemoryPage }],
 *   });
 *
 * A view whose `requires` are not all in the App's composition does not appear (SPEC §5). A component
 * that brings a view installs its folder here (`pikit add`, or `shadcn add @pikit/<view>`).
 */

import type { ComponentType } from "react";
import type { ApiApp } from "./api.ts";

export interface ViewPage {
  /** Relative to /admin, starting with the view's `/<id>`; `:name` is a parameter. */
  path: string;
  component: ComponentType<{ params: Record<string, string> }>;
}

export interface View {
  /** The folder's name. */
  id: string;
  title: string;
  icon?: ComponentType<{ className?: string }>;
  /** Capabilities that must be provided in the App for the view to show. */
  requires?: string[];
  /** Its place in the sidebar, lowest first (default 100). */
  order?: number;
  /** Its pages; the first one is the sidebar's link. */
  pages: ViewPage[];
}

export function defineView(view: View): View {
  for (const page of view.pages) {
    if (page.path !== `/${view.id}` && !page.path.startsWith(`/${view.id}/`)) {
      throw new Error(`view "${view.id}": page ${page.path} is not under /${view.id}`);
    }
  }
  return view;
}

const found = import.meta.glob<{ default: View }>("../views/*/index.tsx", { eager: true });

/** Every view of `src/views/`, in sidebar order. */
export const views: View[] = Object.entries(found)
  .map(([file, module]) => {
    const view = module.default;
    const folder = file.split("/").at(-2);
    if (view?.id !== folder) throw new Error(`src/views/${folder}/index.tsx must default-export defineView({ id: "${folder}", … })`);
    return view;
  })
  .sort((a, b) => (a.order ?? 100) - (b.order ?? 100) || a.title.localeCompare(b.title));

/** The views whose capabilities `app` provides. */
export function visibleViews(app: ApiApp): View[] {
  const provided = (name: string) => (app.capabilities[name]?.providers.length ?? 0) > 0;
  return views.filter((view) => (view.requires ?? []).every(provided));
}
